// App.tsx
import 'dotenv/config';
import React, { useState, useRef } from 'react';
import { render, Box, Text, useInput } from 'ink';
import TextInput from 'ink-text-input';
import Spinner from 'ink-spinner';
import Gradient from 'ink-gradient';
import { runAgent, type LogEvent } from './agent-cli.js';
import { SYSTEM_PROMPT, MODEL, AGENT_NAME } from './constant.js';
import {
  loadSession,
  createNewSessionId,
  getLatestSessionId,
  type Message
} from './session.js';
import { messagesToEntries, type DisplayEntry } from './converter.js';

function resolveSessionId(): { sessionId: string; isResumed: boolean } {
  const args = process.argv.slice(2);
  const resumeIdx = args.indexOf('--resume');

  if (resumeIdx !== -1) {
    const specifiedId = args[resumeIdx + 1];
    const targetId = specifiedId && !specifiedId.startsWith('--')
      ? specifiedId
      : getLatestSessionId();

    if (targetId) {
      return { sessionId: targetId, isResumed: true };
    }
  }

  return { sessionId: createNewSessionId(), isResumed: false };
}

let entryId = 0;

function Header({ sessionId }: { sessionId: string }) {
  return (
    <Box flexDirection="column" padding={1}>
      <Box flexDirection="column" marginBottom={1}>
        <Gradient name="pastel">
          <Text bold>▲ {AGENT_NAME}</Text>
        </Gradient>
        <Text dimColor>model: {MODEL} | session: {sessionId.slice(0, 8)}</Text>
      </Box>
    </Box>

  );
}

function EntryLine({ entry }: { entry: DisplayEntry }) {
  switch (entry.kind) {
    case 'user':
      return (
        <Box marginTop={1}>
          <Text color="cyanBright" bold>{'❯ '}</Text>
          <Text color="cyanBright">{entry.text}</Text>
        </Box>
      );
    case 'reasoning':
      return (
        <Box marginTop={1} paddingLeft={2} borderStyle="round" borderColor="gray" flexDirection="column">
          <Text dimColor italic>{entry.text}</Text>
        </Box>
      );
    case 'tool_call':
      return (
        <Box marginTop={1}>
          <Text color="yellowBright">{'⚡ '}</Text>
          <Text color="yellow">{entry.text}</Text>
        </Box>
      );
    case 'tool_result':
      return (
        <Box paddingLeft={2} flexDirection="column">
          <Text color="greenBright" dimColor>
            {entry.text.length > 400 ? entry.text.slice(0, 400) + '…' : entry.text}
          </Text>
        </Box>
      );
    case 'assistant':
      return (
        <Box marginTop={1} paddingLeft={1} flexDirection="column">
          <Text color="white">{entry.text}</Text>
        </Box>
      );
    case 'info':
      return (
        <Box marginTop={1}>
          <Text color="magentaBright">{'ℹ '}</Text>
          <Text color="magenta">{entry.text}</Text>
        </Box>
      );
  }
}

function App() {
  const confirmResolverRef = useRef<((val: boolean) => void) | null>(null);
  const [input, setInput] = useState('');
  const [isProcessing, setIsProcessing] = useState(false);
  const [pendingConfirm, setPendingConfirm] = useState<string | null>(null);
  const sessionRef = useRef(resolveSessionId());
  const sessionId = sessionRef.current.sessionId;

  const messagesRef = useRef<Message[]>(initMessages());
  const [entries, setEntries] = useState<DisplayEntry[]>(() => {
    return messagesToEntries(messagesRef.current);
  });
  function initMessages(): Message[] {
    const loaded = loadSession(sessionId);
    if (loaded.length === 0) {
      loaded.push({ role: 'system', content: SYSTEM_PROMPT });
    }
    return loaded;
  }

  function pushEntry(kind: DisplayEntry['kind'], text: string) {
    setEntries(prev => [...prev, { id: entryId++, kind, text }]);
  }

  function appendToLastAssistant(delta: string) {
    setEntries(prev => {
      const last = prev[prev.length - 1];
      if (last?.kind === 'assistant') {
        const updated = [...prev];
        updated[updated.length - 1] = { ...last, text: last.text + delta };
        return updated;
      }
      return [...prev, { id: entryId++, kind: 'assistant', text: delta }];
    });
  }

  function appendToLastReasoning(delta: string) {
    setEntries(prev => {
      const last = prev[prev.length - 1];
      if (last?.kind === 'reasoning') {
        const updated = [...prev];
        updated[updated.length - 1] = { ...last, text: last.text + delta };
        return updated;
      }
      return [...prev, { id: entryId++, kind: 'reasoning', text: delta }];
    });
  }

  async function handleConfirm(description: string): Promise<boolean> {
    setPendingConfirm(description);
    return new Promise<boolean>(resolve => {
      confirmResolverRef.current = resolve;
    });
  }

  useInput((inputChar) => {
    if (!pendingConfirm) return;
    const lower = inputChar.toLowerCase();
    if (lower === 'y' || lower === 'n') {
      const resolver = confirmResolverRef.current;
      setPendingConfirm(null);
      confirmResolverRef.current = null;
      resolver?.(lower === 'y');
    }
  });

  async function handleSubmit(value: string) {
    if (!value.trim() || isProcessing) return;

    if (value.trim().toLowerCase() === 'exit') {
      process.exit(0);
    }

    pushEntry('user', value);
    setInput('');
    setIsProcessing(true);

    messagesRef.current.push({ role: 'user', content: value });

    const onLog = (event: LogEvent) => {
      switch (event.type) {
        case 'reasoning_delta':
          appendToLastReasoning(event.content);
          break;
        case 'tool_call':
          pushEntry('tool_call', `${event.name}(${JSON.stringify(event.args)})`);
          break;
        case 'tool_result':
          pushEntry('tool_result', event.content);
          break;
        case 'assistant_delta':
          appendToLastAssistant(event.content);
          break;
        case 'info':
          pushEntry('info', event.content);
          break;
      }
    };
    messagesRef.current = await runAgent(sessionId, messagesRef.current, {
      onLog,
      onConfirm: handleConfirm,
    });
    setIsProcessing(false);
  }

  return (
    <Box flexDirection="column" padding={1}>
      <Header sessionId={sessionId} />

      <Box flexDirection="column">
        {entries.map(entry => (
          <EntryLine key={entry.id} entry={entry} />
        ))}
      </Box>

      {pendingConfirm && (
        <Box marginTop={1} paddingX={1} borderStyle="round" borderColor="red">
          <Text color="redBright" bold>{'⚠ '}</Text>
          <Text color="red">Allow: {pendingConfirm}?  </Text>
          <Text dimColor>(y/n)</Text>
        </Box>
      )}

      {!pendingConfirm && (
        <Box marginTop={1} paddingX={1} borderStyle="round" borderColor={isProcessing ? 'gray' : 'cyan'}>
          <Text color="cyanBright" bold>{'❯ '}</Text>
          <TextInput value={input} onChange={setInput} onSubmit={handleSubmit} focus={!isProcessing} />
        </Box>
      )}

      {isProcessing && (
        <Box marginTop={1}>
          <Text color="cyan">
            <Spinner type="dots" />
          </Text>
          <Text dimColor> thinking...</Text>
        </Box>
      )}

      <Box marginTop={1}>
        <Text dimColor>type "exit" to quit</Text>
      </Box>
    </Box>
  );
}

render(<App />);

// converter.ts
import type { Message } from './session.js';

export type DisplayEntry = {
  id: number;
  kind: 'user' | 'reasoning' | 'tool_call' | 'tool_result' | 'assistant' | 'info';
  text: string;
};

export function messagesToEntries(messages: Message[], startId = 0): DisplayEntry[] {
  const entries: DisplayEntry[] = [];
  let id = startId;

  for (const msg of messages) {
    // Skip System Prompts
    if (msg.role === 'system') continue;

    // Detect Context Compaction summaries
    if (msg.role === 'user' && typeof msg.content === 'string' && msg.content.startsWith('[SYSTEM SUMMARY]:')) {
      entries.push({
        id: id++,
        kind: 'info',
        text: `Context Compacted: ${msg.content.replace('[SYSTEM SUMMARY]:', '').trim()}`,
      });
      continue;
    }

    if (msg.role === 'user' && msg.content) {
      entries.push({ id: id++, kind: 'user', text: msg.content });
    }

    if (msg.role === 'assistant') {
      if (msg.reasoning) {
        entries.push({ id: id++, kind: 'reasoning', text: msg.reasoning });
      }
      if (msg.content) {
        entries.push({ id: id++, kind: 'assistant', text: msg.content });
      }
      for (const call of msg.toolCalls ?? []) {
        entries.push({
          id: id++,
          kind: 'tool_call',
          text: `${call.function.name}(${call.function.arguments})`,
        });
      }
    }
    if (msg.role === 'tool' && msg.content) {
      entries.push({ id: id++, kind: 'tool_result', text: msg.content });
    }
  }

  return entries;
}

import fs from 'fs';
import { execFileSync, execSync } from 'child_process';
import type { Message } from './session.js';
import { tools } from './tools.js';
import { MODEL, SUBAGENT_TOOLS } from './constant.js';
import { client } from './openrouter.js';
import { formatRgOutput } from './helpers.js';

export function runBash(command: string): string {
  try {
    return execSync(command, { encoding: 'utf-8', timeout: 10_000 });
  } catch (err: any) {
    return `ERROR: ${err.stdout ?? ''}${err.stderr ?? err.message}`;
  }
}

export function readFile(path: string): string {
  try {
    return fs.readFileSync(path, 'utf-8');
  } catch (err: any) {
    return `ERROR: ${err.message}`;
  }
}

export function writeFile(path: string, content: string): string {
  try {
    fs.writeFileSync(path, content, 'utf-8');
    return `File written successfully to ${path}`;
  } catch (err: any) {
    return `ERROR: ${err.message}`;
  }
}

export function editFile(path: string, oldContent: string, newContent: string): string {
  try {
    const content = fs.readFileSync(path, 'utf-8');
    const occurences = content.split(oldContent).length - 1;
    if (occurences === 0) {
      return `ERROR: The string "${oldContent}" was not found in the file.`;
    }
    const updatedContent = content.replace(oldContent, newContent);
    fs.writeFileSync(path, updatedContent, 'utf-8');
    return `Successfully replaced ${occurences} occurence(s) of "${oldContent}" with "${newContent}" in ${path}`;
  } catch (err: any) {
    return `ERROR: ${err.message}`;
  }

}

export async function spawnSubAgent(task: string): Promise<string> {
  const MAX_ITERATIONS = 10;
  let subMessages: Message[] = [
    { role: "system", content: "..." },
    { role: "user", content: task },
  ];
  const subToolSchemas = tools.filter(t => SUBAGENT_TOOLS.includes(t.function.name));

  for (let i = 0; i < MAX_ITERATIONS; i++) {
    const response = await client.chat.send({
      chatRequest: { model: MODEL, messages: subMessages, tools: subToolSchemas },
    });
    const message = (response as any).choices[0].message;
    const rawToolCalls = message.toolCalls ?? [];

    subMessages.push({
      role: "assistant",
      content: message.content,
      toolCalls: rawToolCalls.length ? rawToolCalls : undefined,
    });
    if (!rawToolCalls.length) {
      return message.content ?? "(sub-agent returned no content)";
    }

    if (!rawToolCalls.length) {
      return message.content ?? "(sub-agent returned no content)";
    }

    for (const call of rawToolCalls) {
      const args = JSON.parse(call.function.arguments);
      const executor = toolExecutors[call.function.name];
      const result = executor
        ? await executor(args)
        : `ERROR: No executor found for tool: ${call.function.name}`;
      subMessages.push({
        role: "tool",
        toolCallId: call.id,
        content: result,
      });
    }
  }

  return "(sub-agent hit max iterations without a final answer)";
}

export function searchCodebase(pattern: string, path: string = '.', maxResults: number = 60): string {
  const cappedMax = Math.min(maxResults, 150);
  try {
    const output = execFileSync(
      'rg',
      [
        '--json', '-n', '-C', '2', '--max-count', String(cappedMax),
        '--glob', '!node_modules',
        '--glob', '!dist',
        '--glob', '!.git',
        '--glob', '!*.lock',
        '--glob', '!package-lock.json',
        '--', pattern, path,
      ],
      { encoding: 'utf-8', timeout: 10_000, maxBuffer: 10 * 1024 * 1024 }
    );
    return formatRgOutput(output, cappedMax);
  } catch (err: any) {
    if (err.status === 1) return 'No matches found.';
    return `ERROR: ${err.stderr ?? err.message}`;
  }
}
export const toolExecutors: Record<string, (args: any) => string | Promise<string>> = {
  run_bash: (args) => runBash(args.command),
  read_file: (args) => readFile(args.path),
  write_file: (args) => writeFile(args.path, args.content),
  replace_string_in_file: (args) => editFile(args.path, args.stringToReplace, args.newString),
  spawn_sub_agent: (args) => spawnSubAgent(args.task),
  search_code: (args) => searchCodebase(args.pattern, args.path, args.maxResults),
};
